import {defaults,films,parseCube} from './engine.mjs';
const $=id=>document.getElementById(id),canvas=$('canvas'),ctx=canvas.getContext('2d');let settings={...defaults},source,preview,luts=[],selected='',compare=false,serial=0,timer,exporting=false,currentName='iro-demo';const worker=new Worker('./worker.mjs',{type:'module'}),pending=new Map();
const toast=message=>{$('toast').textContent=message;$('toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('toast').hidden=true,5000)};
const groups=[['ÁNH SÁNG',[['exposure','Bù sáng · EV',-3,3,1/3],['dr','Dynamic Range',[100,200,400]],['highlight','Highlight',-2,4,1],['shadow','Shadow',-2,4,1]]],['MÀU SẮC',[['amount','Cường độ màu phim',0,100,1],['wb','Cân bằng trắng',['Auto','Daylight','Cloudy','Tungsten']],['temperature','Nhiệt độ',-100,100,1],['red','WB Shift · Red',-9,9,1],['blue','WB Shift · Blue',-9,9,1],['color','Color',-4,4,1]]],['CHI TIẾT & CHẤT PHIM',[['grain','Grain Effect',[0,8,18]],['sharpness','Sharpness',-4,4,1],['nr','Noise Reduction',-4,4,1]]]];
const labels={100:'DR100',200:'DR200',400:'DR400',0:'Off',8:'Weak',18:'Strong',Auto:'Auto (giữ WB ảnh)',Daylight:'Daylight',Cloudy:'Cloudy',Tungsten:'Tungsten'};
for(const [title,controls] of groups){const group=document.createElement('section');group.className='control-group';const h=document.createElement('div');h.className='group-title';h.textContent=title;group.append(h);for(const [key,label,min,max,step]of controls){const d=document.createElement('div');d.className='control';const l=document.createElement('label');l.htmlFor=key;l.textContent=label;const input=document.createElement(Array.isArray(min)?'select':'input');input.id=key;if(Array.isArray(min)){for(const v of min){const o=new Option(labels[v]||v,v);input.add(o)}l.append(input);d.append(l)}else{input.type='range';input.min=min;input.max=max;input.step=step;const output=document.createElement('output');output.id=key+'Value';l.append(output);d.append(l,input)}input.oninput=()=>{settings[key]=key==='wb'?input.value:Number(input.value);sync();render()};group.append(d)}$('controls').append(group)}
Object.keys(films).forEach((name,i)=>{const b=document.createElement('button');b.className='film';b.dataset.film=name;const sw=document.createElement('span');sw.className='swatch';sw.style.filter=`saturate(${films[name][0]}) contrast(${films[name][1]}) hue-rotate(${i*5}deg)`;b.append(sw,document.createTextNode(name));const small=document.createElement('small');small.textContent=String(i+1).padStart(2,'0');b.append(small);b.onclick=()=>{settings.film=name;sync();render()};$('films').append(b)});
function sync(){for(const [,list]of groups)for(const [key]of list){$(key).value=settings[key];if($(key+'Value'))$(key+'Value').textContent=key==='amount'?settings[key]+'%':key==='exposure'?(settings[key]>0?'+':'')+Number(settings[key].toFixed(2)):(settings[key]>0?'+':'')+settings[key]}document.querySelectorAll('.film').forEach(b=>b.classList.toggle('active',b.dataset.film===settings.film));$('lookTitle').textContent=settings.film;$('imageTag').textContent='IRO / '+(compare?'ORIGINAL':settings.film.toUpperCase());$('lutAmount').value=settings.lutAmount;$('lutValue').textContent=settings.lutAmount+'%'}
function job(data){return new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});worker.postMessage({...data,id})})}worker.onmessage=({data:d})=>{const p=pending.get(d.id);if(!p)return;pending.delete(d.id);d.error?p.reject(Error(d.error)):p.resolve(d)};worker.onerror=()=>{for(const p of pending.values())p.reject(Error('Bộ xử lý ảnh gặp lỗi. Hãy tải lại trang.'));pending.clear()};
let renderTimer,version=0;function render(){const v=++version;clearTimeout(renderTimer);if(compare){paint(preview);$('busy').hidden=true;return}renderTimer=setTimeout(async()=>{if(!preview)return;$('busy').hidden=false;try{const result=await job({pixels:preview.data,width:preview.width,height:preview.height,settings:{...settings},lut:luts.find(l=>l.id===selected)});if(v===version&&!compare)paint(new ImageData(result.pixels,result.width,result.height))}catch(e){toast(e.message)}finally{if(v===version)$('busy').hidden=true}},70)}
function paint(data){canvas.width=data.width;canvas.height=data.height;ctx.putImageData(data,0,0)}function setSource(c,name,demo=false){source=c;currentName=name;const p=document.createElement('canvas'),scale=Math.min(1,1400/Math.max(c.width,c.height));p.width=Math.round(c.width*scale);p.height=Math.round(c.height*scale);const x=p.getContext('2d');x.drawImage(c,0,0,p.width,p.height);preview=x.getImageData(0,0,p.width,p.height);$('filename').textContent=name;$('imageSize').textContent=demo?'ẢNH MẪU MINH HỌA':`${c.width} × ${c.height}`;$('status').textContent=demo?'Thử màu trên ảnh mẫu hoặc mở ảnh của bạn':'Đã mở ảnh · mọi thay đổi đều có thể đặt lại';render()}
function demo(){const c=document.createElement('canvas');c.width=1200;c.height=900;const x=c.getContext('2d');const sky=x.createLinearGradient(0,0,0,900);sky.addColorStop(0,'#5c8e94');sky.addColorStop(.57,'#d0ccb0');sky.addColorStop(1,'#b49a76');x.fillStyle=sky;x.fillRect(0,0,1200,900);x.fillStyle='#e9d4a1';x.beginPath();x.arc(850,215,65,0,7);x.fill();for(let n=0;n<4;n++){x.fillStyle=['#718781','#526d65','#3d5a4d','#2c4437'][n];x.beginPath();x.moveTo(0,440+n*85);for(let a=0;a<=1200;a+=20)x.lineTo(a,410+n*85+Math.sin(a/180+n*2)*55+Math.cos(a/83)*15);x.lineTo(1200,900);x.lineTo(0,900);x.fill()}x.fillStyle='#cab98f';x.beginPath();x.moveTo(640,580);x.bezierCurveTo(610,680,900,720,690,900);x.lineTo(420,900);x.bezierCurveTo(760,740,570,710,640,580);x.fill();x.fillStyle='#c5b69a';x.fillRect(175,480,205,160);x.fillStyle='#714f37';x.beginPath();x.moveTo(143,485);x.lineTo(272,389);x.lineTo(415,485);x.fill();x.fillStyle='#253c33';x.fillRect(252,554,46,86);x.fillRect(197,524,30,35);x.fillRect(329,524,30,35);for(let a=0;a<80;a++){let px=(a*179)%1200,py=650+(a*47)%250;x.strokeStyle='#879267';x.beginPath();x.moveTo(px,py);x.lineTo(px+7,py-21);x.stroke()}setSource(c,'Hillside / ảnh mẫu minh họa',true)}
async function openPhoto(file){if(!file)return;try{if(file.size>60*1024**2)throw Error('Vui lòng chọn ảnh nhỏ hơn 60 MB.');const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});const scale=Math.min(1,Math.sqrt(24000000/(bitmap.width*bitmap.height)));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();setSource(c,file.name);if(scale<1)toast('Ảnh được giảm xuống 24 MP để xử lý ổn định.')}catch(e){toast('Không mở được ảnh. Hỗ trợ JPEG, PNG, WebP, AVIF. '+e.message)}}
$('open').onclick=()=>$('photo').click();$('photo').onchange=e=>{openPhoto(e.target.files[0]);e.target.value=''};for(const event of ['dragover','dragleave','drop'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.toggle('drag',event==='dragover');if(event==='drop')openPhoto(e.dataTransfer.files[0])});$('compare').onclick=()=>{compare=!compare;$('compare').setAttribute('aria-pressed',compare);$('compare').textContent=compare?'◧  Quay lại ảnh chỉnh':'◧  Xem ảnh gốc';sync();render()};$('reset').onclick=()=>{settings={...defaults};selected='';$('lutSelect').value='';sync();render();toast('Đã đặt lại toàn bộ thông số.')};$('sampleRecipe').onclick=()=>{settings={...defaults,film:'Classic Chrome',dr:200,grain:8,red:1,blue:-1,highlight:-1,shadow:1,color:2,sharpness:2,nr:-2,exposure:2/3};selected='';$('lutSelect').value='';sync();render();toast('Đã áp dụng công thức Classic Chrome từ ảnh bạn gửi.')};
let db;const ready=new Promise(resolve=>{const req=indexedDB.open('iro-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('luts',{keyPath:'id'});req.onerror=()=>{toast('Không lưu được LUT lâu dài trong trình duyệt này.');resolve()};req.onsuccess=()=>{db=req.result;const r=db.transaction('luts').objectStore('luts').getAll();r.onsuccess=()=>{luts=r.result;listLuts();resolve()};r.onerror=()=>resolve()}});
function listLuts(){$('lutSelect').replaceChildren(new Option('Không áp dụng LUT',''));for(const l of luts)$('lutSelect').add(new Option(l.title,l.id));$('lutSelect').value=selected}function persist(l,remove=false){if(!db)return;const t=db.transaction('luts','readwrite');remove?t.objectStore('luts').delete(l.id):t.objectStore('luts').put(l);t.onerror=()=>toast('Bộ nhớ trình duyệt đầy. LUT chỉ dùng được trong phiên này.')}
$('importLut').onclick=()=>$('lutfile').click();$('lutfile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await ready;if(f.size>35*1024**2)throw Error('LUT quá lớn (tối đa 35 MB).');const l=parseCube(await f.text());l.title=l.title==='Custom LUT'?f.name:l.title;l.id=crypto.randomUUID();luts.push(l);selected=l.id;persist(l);listLuts();render();toast('Đã thêm LUT: '+l.title)}catch(err){toast(err.message)}e.target.value=''};$('lutSelect').onchange=e=>{selected=e.target.value;render()};$('lutAmount').oninput=e=>{settings.lutAmount=+e.target.value;sync();render()};$('removeLut').onclick=()=>{if(!selected)return;persist({id:selected},true);luts=luts.filter(l=>l.id!==selected);selected='';listLuts();render()};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('saveRecipe').onclick=()=>{download(new Blob([JSON.stringify({app:'IRO',version:1,settings,lutTitle:luts.find(l=>l.id===selected)?.title||null},null,2)],{type:'application/json'}),'iro-recipe.json');toast('Đã lưu recipe. File LUT được quản lý riêng.')} ;$('loadRecipe').onclick=()=>$('recipefile').click();$('recipefile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('File recipe quá lớn.');const r=JSON.parse(await f.text());if(r.app!=='IRO'||r.version!==1||!r.settings)throw Error('Recipe không đúng định dạng IRO.');const next={...defaults};for(const [,controls] of groups)for(const [key,,min,max]of controls){const val=r.settings[key];if(Array.isArray(min)){if(!min.includes(val))throw Error('Thông số không hợp lệ: '+key)}else if(typeof val!=='number'||!Number.isFinite(val)||val<min||val>max)throw Error('Thông số ngoài phạm vi: '+key);next[key]=val}if(!Object.hasOwn(films,r.settings.film))throw Error('Màu phim không hợp lệ.');next.film=r.settings.film;const amount=r.settings.lutAmount;if(typeof amount!=='number'||!Number.isFinite(amount)||amount<0||amount>100)throw Error('Cường độ LUT không hợp lệ.');next.lutAmount=amount;await ready;const lut=luts.find(l=>l.title===r.lutTitle);settings=next;selected=lut?.id||'';listLuts();sync();render();toast(r.lutTitle&&!lut?'Đã nhập recipe. Hãy nhập thêm LUT: '+r.lutTitle:'Đã nhập recipe.')}catch(err){toast(err.message)}e.target.value=''};
$('export').onclick=async()=>{if(exporting||!source)return;exporting=true;$('export').disabled=true;$('export').textContent='Đang xuất…';try{const pixels=source.getContext('2d').getImageData(0,0,source.width,source.height);const r=await job({pixels:pixels.data,width:source.width,height:source.height,settings:{...settings},lut:luts.find(l=>l.id===selected)});const c=document.createElement('canvas');c.width=r.width;c.height=r.height;c.getContext('2d').putImageData(new ImageData(r.pixels,r.width,r.height),0,0);const type=$('format').value;const blob=await new Promise(resolve=>c.toBlob(resolve,type,.95));if(!blob)throw Error('Trình duyệt không thể xuất ảnh kích thước này.');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[blob.type]||'png';download(blob,currentName.replace(/\.[^.]+$/,'').replace(/[\\/:*?"<>|]/g,'-')+'-iro.'+ext);toast('Đã xuất ảnh '+r.width+' × '+r.height+' px.')}catch(e){toast(e.message)}finally{exporting=false;$('export').disabled=false;$('export').textContent='Xuất ảnh ↗'}};
sync();demo();
